const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;

/**
 * Import IDs are UUIDs generated by the database/application boundary. Keep
 * the queue ID derived only from that identifier and the dispatch generation
 * so it is stable, bounded, and cannot carry row data or other secrets.
 */
export function isImportId(value: string) {
  return UUID_PATTERN.test(value);
}

/**
 * BullMQ 5 permits a colon-containing custom ID only when it has exactly three
 * colon-separated parts. The fixed `dispatch` marker preserves the full
 * import+generation correlation without putting arbitrary input in a queue
 * key, while remaining compatible with that BullMQ rule.
 */
export function buildImportJobId(importId: string, generation: number) {
  if (!isImportId(importId) || !Number.isSafeInteger(generation) || generation < 1) {
    throw new Error("invalid_import_job_identity");
  }
  return `${importId}:dispatch:${generation}`;
}
